// Calculate statistics for current and previous periods
const currentSales = $input.first().json.data || [];
const previousSales = $input.all()[1]?.json?.data || [];

// Helper functions
function calculateMedian(arr) {
  if (arr.length === 0) return 0;
  const sorted = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2;
}

function calculateAverage(arr) {
  if (arr.length === 0) return 0;
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

// Current period stats
const currentPrices = currentSales.map(s => s.sale_price).filter(p => p);
const currentFloorSizes = currentSales.map(s => s.floor_size).filter(s => s);
const currentDaysOnMarket = currentSales.map(s => s.days_on_market).filter(d => d !== null && d !== undefined);

// Previous period stats
const previousPrices = previousSales.map(s => s.sale_price).filter(p => p);
const previousFloorSizes = previousSales.map(s => s.floor_size).filter(s => s);
const previousDaysOnMarket = previousSales.map(s => s.days_on_market).filter(d => d !== null && d !== undefined);

// Calculate averages
const currentAvgPrice = Math.round(calculateAverage(currentPrices));
const currentMedianPrice = Math.round(calculateMedian(currentPrices));
const previousAvgPrice = Math.round(calculateAverage(previousPrices));

// Calculate price per sqm
const currentPricePerSqm = currentFloorSizes.length > 0
  ? Math.round(currentPrices.reduce((a, b) => a + b, 0) / currentFloorSizes.reduce((a, b) => a + b, 0))
  : 0;

const previousPricePerSqm = previousFloorSizes.length > 0
  ? Math.round(previousPrices.reduce((a, b) => a + b, 0) / previousFloorSizes.reduce((a, b) => a + b, 0))
  : 0;

// Calculate changes
const priceChangePercent = previousAvgPrice > 0
  ? Math.round(((currentAvgPrice - previousAvgPrice) / previousAvgPrice) * 100 * 100) / 100
  : 0;

const volumeChangePercent = previousSales.length > 0
  ? Math.round(((currentSales.length - previousSales.length) / previousSales.length) * 100 * 100) / 100
  : 0;

const daysOnMarketChange = previousDaysOnMarket.length > 0 && currentDaysOnMarket.length > 0
  ? Math.round(calculateAverage(currentDaysOnMarket) - calculateAverage(previousDaysOnMarket))
  : 0;

// Property type breakdown
const propertyTypes = {};
currentSales.forEach(s => {
  const type = s.property_type || 'Unknown';
  propertyTypes[type] = (propertyTypes[type] || 0) + 1;
});

// Most active suburbs
const suburbCounts = {};
currentSales.forEach(s => {
  const suburb = s.area || 'Unknown';
  suburbCounts[suburb] = (suburbCounts[suburb] || 0) + 1;
});

const mostActiveSuburbs = Object.entries(suburbCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name, count]) => name);

// Average days on market
const avgDaysOnMarket = currentDaysOnMarket.length > 0
  ? Math.round(calculateAverage(currentDaysOnMarket))
  : 0;

const stats = {
  area: $input.first().json.area,
  city: $input.first().json.city,
  period_start: $input.first().json.period_start,
  period_end: $input.first().json.period_end,
  current_period: {
    total_sales: currentSales.length,
    average_price: currentAvgPrice,
    median_price: currentMedianPrice,
    price_per_sqm: currentPricePerSqm,
    avg_days_on_market: avgDaysOnMarket,
    property_types: propertyTypes,
    most_active_suburbs: mostActiveSuburbs
  },
  previous_period: {
    total_sales: previousSales.length,
    average_price: previousAvgPrice,
    price_per_sqm: previousPricePerSqm
  },
  comparisons: {
    price_change_percent: priceChangePercent,
    volume_change_percent: volumeChangePercent,
    days_on_market_change: daysOnMarketChange
  },
  month: new Date($input.first().json.period_start).toLocaleString('en-ZA', { month: 'long' }),
  year: new Date($input.first().json.period_start).getFullYear()
};

return [stats];

