const groqResponse = $input.first().json;
const stats = $input.first().json;

// Extract the AI-generated content from Groq response
let aiContent;
try {
  aiContent = JSON.parse(groqResponse.choices?.[0]?.message?.content || '{}');
} catch (e) {
  // Try to extract JSON from markdown code block
  const content = groqResponse.choices?.[0]?.message?.content || '';
  const jsonMatch = content.match(/```json\s*([\s\S]*?)```/) || content.match(/{[\s\S]*}/);
  if (jsonMatch) {
    try {
      aiContent = JSON.parse(jsonMatch[1] || jsonMatch[0]);
    } catch (e2) {
      aiContent = {
        report_title: `Market Report - ${stats.area} - ${stats.month} ${stats.year}`,
        executive_summary: 'Error parsing AI response. Please review raw data.',
        key_findings: ['Data available in raw statistics'],
        full_report_markdown: content
      };
    }
  } else {
    aiContent = {
      report_title: `Market Report - ${stats.area} - ${stats.month} ${stats.year}`,
      executive_summary: content.substring(0, 500),
      key_findings: ['See full report'],
      full_report_markdown: content
    };
  }
}

// Combine stats with AI content
const report = {
  id: Math.random().toString(36).substring(2, 15),
  area: stats.area,
  city: stats.city,
  period_start: stats.period_start,
  period_end: stats.period_end,
  report_title: aiContent.report_title || `Market Report - ${stats.area} - ${stats.month} ${stats.year}`,
  executive_summary: aiContent.executive_summary || '',
  key_findings: Array.isArray(aiContent.key_findings) ? aiContent.key_findings : [],
  price_analysis: aiContent.price_analysis || '',
  volume_analysis: aiContent.volume_analysis || '',
  hotspots: Array.isArray(aiContent.hotspots) ? aiContent.hotspots : [],
  buyer_insights: aiContent.buyer_insights || '',
  outlook: aiContent.outlook || '',
  recommendations_sellers: aiContent.recommendations_for_sellers || '',
  recommendations_buyers: aiContent.recommendations_for_buyers || '',
  full_report: aiContent.full_report_markdown || '',
  statistics: {
    total_sales: stats.current_period.total_sales,
    average_price: stats.current_period.average_price,
    median_price: stats.current_period.median_price,
    price_per_sqm: stats.current_period.price_per_sqm,
    avg_days_on_market: stats.current_period.avg_days_on_market,
    price_change_percent: stats.comparisons.price_change_percent,
    volume_change_percent: stats.comparisons.volume_change_percent
  },
  generated_at: new Date().toISOString()
};

return [report];

